update public.question_bank
set question_text = 'Em 01/01/2025, uma sociedade empresária investiu R$ 90.000 em uma aplicação financeira de longo prazo. Os juros são reconhecidos mensalmente e adicionados ao principal, para resgate no final do período da aplicação. Ao analisar as movimentações nas demonstrações contábeis, o perito contábil constatou que, mensalmente, em 2025, houve',
    options = '{"A":"reconhecimento de receita financeira e aumento no ativo circulante.","B":"reconhecimento de receita financeira e aumento no ativo realizável a longo prazo.","C":"reconhecimento de receita financeira e aumento em investimentos.","D":"reconhecimento de receita operacional e aumento no ativo realizável a longo prazo.","E":"reconhecimento de receita operacional e aumento em investimentos."}'::jsonb,
    explanation = 'A alternativa correta é B. Os juros reconhecidos todos os meses representam receita financeira, pois decorrem da aplicação de recursos e não da atividade principal de venda de produtos ou prestação de serviços. Como a aplicação é de longo prazo, o principal e os juros incorporados permanecem no Ativo não circulante, no grupo do Ativo Realizável a Longo Prazo. O fato de os juros serem adicionados ao principal aumenta o direito a receber, mas não transforma a aplicação em investimento societário. Investimentos são participações permanentes ou outros direitos enquadrados nesse grupo, enquanto a aplicação financeira continua sendo um direito financeiro realizável a longo prazo. Portanto: receita financeira + aumento no ARLP. A alternativa A erra o prazo; C confunde aplicação financeira com investimento; D e E tratam os juros como receita operacional, quando são receita financeira.'
where id = '04ee8272-b52d-4312-8c93-b1c2a7ecf857';
